-- Catálogo de cámaras, Tanda 2: Nikon (Diego, 20-nov: «Sí a todo»).
--
-- 215 modelos de film de la historia oficial de productos de Nikon: solo
-- datos sueltos (nombre, año, tipo, formato y montura), con la página de su
-- década como fuente. Cada nombre regional o comercial es su propio modelo
-- (F80 y N80, Nikomat y Nikkormat, One-Touch); las variantes con fechador
-- (QD, D) son una. Revisión: docs privados, TANDA-2-NIKON. Por clave: nunca
-- duplica ni pisa lo corregido desde el panel.

insert into public.camera_models
  (manufacturer_id, name, type, format, mount_id, interchangeable, year_from,
   source, source_ref, status)
select app_private.manufacturer_for('Nikon', null, true), v.name, v.type, v.format,
       (select m.id from public.lens_mounts m where m.status = 'approved' and m.name = v.mount),
       v.interchangeable, v.year, 'nikon', v.ref, 'approved'
from (values
  ('I', 'Rangefinder', '35mm', 'Nikon S', true, 1948, 'https://imaging.nikon.com/imaging/information/products_history/1960/'),
  ('M', 'Rangefinder', '35mm', 'Nikon S', true, 1949, 'https://imaging.nikon.com/imaging/information/products_history/1960/'),
